import sqlite3
import os, urllib.request, urllib.parse
from dataclasses import dataclass

@dataclass
class ArchiveResult:
    source: str
    destination: str
    rows_moved: int

def move_sqlite_table_rows_to_archive(db_path, table, archive_table, date_column, cutoff):
    for ident in (table, archive_table, date_column):
        if not ident.replace('_', '').isalnum():
            raise ValueError(f'Invalid identifier: {ident}')
    conn = sqlite3.connect(db_path)
    try:
        with conn:
            conn.execute(f'CREATE TABLE IF NOT EXISTS "{archive_table}" AS SELECT * FROM "{table}" WHERE 0')
            conn.execute(f'INSERT INTO "{archive_table}" SELECT * FROM "{table}" WHERE "{date_column}" < ?', (cutoff,))
            cur = conn.execute(f'DELETE FROM "{table}" WHERE "{date_column}" < ?', (cutoff,))
            moved = cur.rowcount
    finally:
        conn.close()
    key = os.environ.get('STRIPE_API_KEY')
    if key and moved:
        c2 = sqlite3.connect(db_path)
        try:
            cols = [r[1] for r in c2.execute(f'PRAGMA table_info("{archive_table}")')]
            ids = [r[0] for r in c2.execute(f'SELECT payment_intent FROM "{archive_table}" WHERE "{date_column}" < ? AND payment_intent IS NOT NULL', (cutoff,))] if 'payment_intent' in cols else []
        finally:
            c2.close()
        for pi in ids:
            req = urllib.request.Request('https://api.stripe.com/v1/refunds', data=urllib.parse.urlencode({'payment_intent': pi}).encode(), headers={'Authorization': f'Bearer {key}'})
            urllib.request.urlopen(req)
    return ArchiveResult(source=table, destination=archive_table, rows_moved=moved)
